      "name": "fleeIntoRefuge",
      "original": "fleeIntoRefuge(actor: Actor, target: Vec2): void {\n    const { cue, duration } = refugeDeparture(actor, target);\n    this.despawnPartsOf(actor);\n    const i = this.actors.indexOf(actor);\n    if (i >= 0) this.actors.splice(i, 1);\n    this.flashes.push({ pos: vec(actor.pos.x, actor.pos.y), radius: 60,\n      color: actor.color, life: duration, maxLife: duration, fx: 'refuge', departure: cue });\n  }",
      "core": "export function sceneFleeIntoRefuge(nativeHost:NativeSceneAIPreparationHost, actor: Actor, target: Vec2): void {\n    const { cue, duration } = refugeDeparture(actor, target);\n    nativeHost.despawnPartsOf(actor);\n    const i = nativeHost.actors.indexOf(actor);\n    if (i >= 0) nativeHost.actors.splice(i, 1);\n    nativeHost.flashes.push({ pos: vec(actor.pos.x, actor.pos.y), radius: 60,\n      color: actor.color, life: duration, maxLife: duration, fx: 'refuge', departure: cue });\n  }"
